            // Get the third cell (index 2)
            const cell = cells[2];
            // Get text content, trim
            let text = cell.textContent.trim();
            // Remove any footnote references like † or *?
            // Just keep the main text
            birthplaceStrings.push(text);
        }
    }
    return birthplaceStrings;
}"}

